/* JLSI interactive prototype. All records and role switching are demonstration-only. */
(() => {
'use strict';
const KEY='jlsi-prototype-v1', LANG='jlsi-language';
const clone=x=>JSON.parse(JSON.stringify(x));
let state=clone(window.JLSI_SEED),lang='ar',role='coordinator';
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.programs))state={...state,...saved};lang=localStorage.getItem(LANG)==='en'?'en':'ar';role=localStorage.getItem('jlsi-role')||role;}catch{}
const page=document.body.dataset.page||'home';
let filter='all',query='',activeTab='overview',calendarMonth=10,attendanceDate='2026-10-20',selectedProgram='JLSI-026';
let modalFocus=null,toastTimer;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const tr=(ar,en)=>lang==='ar'?ar:en;
const text=(obj,key='')=>key?obj[key+(lang==='ar'?'Ar':'En')]:obj[lang];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v).toLocaleString(lang==='ar'?'ar-BH':'en-GB');
const date=v=>new Intl.DateTimeFormat(lang==='ar'?'ar-BH':'en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v+'T12:00:00'));
const amount=v=>`${num(v)} ${tr('د.ب','BHD')}`;
const paths={
 scales:'<path d="M12 3v17M5 20h14M4 7h16M5 7l-3 7h6L5 7Zm14 0-3 7h6l-3-7Z"/><path class="accent" d="M9 3h6M2 14c1 3 5 3 6 0M16 14c1 3 5 3 6 0"/>',
 home:'<path d="m3 10 9-8 9 8M5 8v13h14V8M10 21v-7h4v7"/><path class="accent" d="M16 4v4"/>',
 dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path class="accent" d="M14 14h7v7h-7z"/>',
 programs:'<path d="M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3V4ZM12 6v15"/><path class="accent" d="M6 8h3M6 12h3M15 8h3M15 12h3"/>',
 applications:'<path d="M13 21H4V3h12v9M7 7h6M7 11h4"/><path class="accent" d="m13 18 5-5 3 3-5 5h-3v-3Z"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v5M17 3v5M3 10h18"/><path class="accent" d="m8 15 3 3 5-5"/>',
 trainers:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M15 3a4 4 0 0 1 0 8"/><path class="accent" d="m18 16 2 2 3-4M19 12v-1"/>',
 attendance:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M9 3h6v4H9V3ZM8 12h3M8 16h3"/><path class="accent" d="m14 15 2 2 3-4"/>',
 assessments:'<path d="M5 21H3V3h15v7M7 7h7M7 11h5"/><path class="accent" d="m11 17 7-7 3 3-7 7-4 1 1-4Z"/>',
 evaluations:'<path d="M7 4H3v17h18V4h-4M8 3h8v4H8V3ZM7 11h3M7 15h3"/><path class="accent" d="m13 14 2 2 3-4"/>',
 certificates:'<path d="M12 19H3V3h13l4 4v6M16 3v5h4M7 7h5M7 11h6"/><circle class="accent" cx="17" cy="16" r="4"/><path class="accent" d="m14 19-1 4 4-2 4 2-1-4"/>',
 finance:'<path d="M3 7h18M5 7v10M10 7v10M15 7v10M20 7v10M2 21h20M3 17h18L3 17ZM2 7l10-5 10 5"/><path class="accent" d="M12 3v1"/>',
 media:'<rect x="3" y="4" width="18" height="17" rx="2"/><circle class="accent" cx="8" cy="9" r="2"/><path d="m3 18 6-5 4 4 4-6 4 5"/>',
 settings:'<circle cx="12" cy="12" r="4"/><path d="m10 2-1 3-3 1-3-1-1 4 3 2v3l-2 2 2 3 3-1 3 1 1 3 4-1v-3l3-2 3 1 1-4-3-2V8l2-2-3-3-2 2-3-1-1-2Z"/><path class="accent" d="M12 8a4 4 0 0 1 4 4"/>',
 reports:'<path d="M4 3v18h18M8 17v-5M13 17V8"/><path class="accent" d="M18 17V4"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
 arrow:'<path d="M20 12H4m6-6-6 6 6 6"/>',
 plus:'<path d="M12 4v16M4 12h16"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path class="accent" d="M12 6v6l4 2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 location:'<path d="M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0Z"/><circle class="accent" cx="12" cy="9" r="2"/>',
 file:'<path d="M14 2H4v20h16V8l-6-6v6h6M8 12h8M8 16h6"/>',
 star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1 3-6Z"/>'
};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const services=[
 ['dashboard','dashboard','لوحة المتابعة','Dashboard','مؤشرات التدريب والمهام اليومية','Training insights and daily tasks','admin'],
 ['programs','programs','البرامج التدريبية','Training programs','استعرض البرامج وسجّل مشاركتك','Explore programs and register','training'],
 ['applications','applications','الترشيحات والطلبات','Nominations & requests','تقديم الترشيحات ومتابعة حالتها','Submit and track nominations','my'],
 ['schedule','calendar','الجدول التدريبي','Training calendar','مواعيد الدورات والقاعات','Course dates and training rooms','training'],
 ['trainers','trainers','المدربون والمواد','Trainers & materials','الخبرات والحقائب التدريبية','Expertise and learning materials','training'],
 ['attendance','attendance','الحضور والغياب','Attendance','تسجيل الحضور ومتابعة الالتزام','Check in and track participation','my'],
 ['assessments','assessments','الاختبارات والدرجات','Exams & grades','التكليفات ونتائج المتدربين','Assignments and trainee results','training'],
 ['evaluations','evaluations','التقييم وأثر التدريب','Training evaluation','قياس جودة البرامج وأثرها','Measure quality and impact','my'],
 ['certificates','certificates','الشهادات والإفادات','Certificates','إصدار شهادات المشاركة والاجتياز','Issue attendance and completion awards','my'],
 ['finance','finance','المستحقات والمصروفات','Payments & expenses','طلبات الصرف وتكاليف البرامج','Payment requests and program costs','admin'],
 ['reports','reports','التقارير والإحصاءات','Reports & analytics','تقارير التدريب القابلة للتصدير','Export training performance reports','admin'],
 ['media','media','الأرشيف الإعلامي','Media archive','توثيق الفعاليات والمرفقات','Event coverage and attachments','admin']
];
const titles=Object.fromEntries(services.map(s=>[s[0],[s[2],s[3]]]));titles.settings=['إعدادات النظام','System settings'];titles.program=['تفاصيل البرنامج','Program details'];
const roles={coordinator:['منسق التدريب','Training coordinator'],director:['مدير المعهد','Institute director'],trainer:['المدرب','Trainer'],trainee:['المتدرب','Trainee'],stakeholder:['ممثل الجهة','Organization representative'],finance:['الشؤون المالية','Finance officer']};
const statusNames={open:['متاح للتسجيل','Open for registration'],pending:['بانتظار الاعتماد','Pending approval'],approved:['معتمد','Approved'],rejected:['مرفوض','Rejected'],waiting:['قائمة الانتظار','Waitlisted'],completed:['مكتمل','Completed'],paid:['تم الصرف','Paid'],present:['حاضر','Present'],absent:['غائب','Absent'],unmarked:['لم يُسجّل','Not recorded'],draft:['مسودة','Draft']};
const badge=s=>`<span class="badge ${s}">${tr(...(statusNames[s]||[s,s]))}</span>`;
const category=c=>tr(...({law:['التشريع والقانون','Legislation & law'],judicial:['المهارات القضائية','Judicial practice'],rights:['حقوق الإنسان','Human rights']}[c]||[c,c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast(tr('تعذر الحفظ. مساحة المتصفح غير كافية.','Unable to save. Browser storage is full.'));return false;}}
function activity(ar,en){state.activities.unshift({ar,en,time:new Date().toISOString()});state.activities=state.activities.slice(0,20);save();}
function toast(msg){clearTimeout(toastTimer);$('#toast').innerHTML=icon('check')+esc(msg);$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function shell(){
 document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.documentElement.classList.toggle('large-text',state.settings.largeText);
 const current=page==='home'?tr('الخدمات الإلكترونية','Electronic services'):tr(...(titles[page]||titles.dashboard));
 document.title=`${current} | ${tr('معهد الدراسات القضائية والقانونية','Judicial & Legal Studies Institute')}`;
 $('#app').innerHTML=`<div class="topline"></div><header class="masthead"><div class="container header-inner"><a class="brand" href="index.html" aria-label="${tr('الصفحة الرئيسية','Home')}"><span class="brand-mark">${icon('scales')}</span><div class="brand-text"><div class="brand-country">${tr('مملكة البحرين','KINGDOM OF BAHRAIN')}</div><strong>${tr('معهد الدراسات القضائية والقانونية','Judicial & Legal Studies Institute')}</strong><small>${tr('Judicial & Legal Studies Institute','معهد الدراسات القضائية والقانونية')}</small></div></a><div class="header-actions"><span class="demo-badge">${tr('نموذج تفاعلي','Interactive prototype')}</span><button id="language-toggle" class="language" data-action="language" lang="${lang==='ar'?'en':'ar'}">${icon('globe')}${tr('English','العربية')}</button></div></div></header><nav class="utility" aria-label="${tr('القائمة الرئيسية','Main navigation')}"><div class="container utility-inner"><div class="utility-links"><a href="index.html" class="${page==='home'?'active':''}">${tr('الخدمات الإلكترونية','E-services')}</a><a href="programs.html">${tr('البرامج التدريبية','Programs')}</a><a href="applications.html" class="optional">${tr('متابعة الطلبات','Track requests')}</a></div><label class="role-wrap"><span>${tr('استعراض بصفة','Preview as')}</span><select id="role-select" aria-label="${tr('الدور التجريبي','Demo role')}">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${tr(...v)}</option>`).join('')}</select></label></div></nav><main class="container main-content" id="main"><div class="page-title"><div class="eyebrow">${tr('بوابة التدريب والتطوير القضائي','JUDICIAL TRAINING & DEVELOPMENT')}</div><h1>${page==='home'?tr('الخدمات الإلكترونية للمعهد','Institute electronic services'):current}</h1><p>${page==='home'?tr('خدمات متكاملة لمسيرة تدريبية أكثر سهولة وفاعلية','Connected services for a seamless training journey'):tr('إدارة التدريب، خطوة بخطوة','Manage every step of the training journey')}</p><span class="title-rule"></span></div><nav class="breadcrumb" aria-label="${tr('مسار التنقل','Breadcrumb')}"><a href="index.html" aria-label="${tr('الرئيسية','Home')}">${icon('home')}</a><span class="optional">${tr('معهد الدراسات القضائية والقانونية','Judicial & Legal Studies Institute')}</span><span class="sep">${tr('‹','›')}</span><a href="index.html">${tr('الخدمات الإلكترونية','E-services')}</a>${page!=='home'?`<span class="sep">${tr('‹','›')}</span><span class="current" aria-current="page">${current}</span>`:''}</nav><div id="content"></div></main><footer class="footer"><div class="container footer-inner"><div>© 2026 ${tr('معهد الدراسات القضائية والقانونية','Judicial & Legal Studies Institute')}<small>${tr('نموذج تجريبي للمراجعة • جميع الأسماء والسجلات بيانات توضيحية','Prototype for review • All names and records are fictional')}</small></div><div class="footer-links"><a href="settings.html">${tr('الإعدادات','Settings')}</a><a href="#" data-action="help">${tr('دليل الاستخدام','User guide')}</a><a href="#" data-action="about">${tr('عن النموذج','About')}</a></div></div></footer>`;
 renderPage();
}
function sidebar(){const visible=role==='trainee'?['dashboard','programs','applications','schedule','attendance','evaluations','certificates']:role==='finance'?['dashboard','programs','finance','reports']:role==='trainer'?['dashboard','schedule','trainers','attendance','assessments','evaluations']:services.map(s=>s[0]);return `<aside class="sidebar" aria-label="${tr('خدمات التدريب','Training services')}"><div class="sidebar-title">${tr('إدارة التدريب','TRAINING MANAGEMENT')}</div>${services.filter(s=>visible.includes(s[0])).map(s=>`<a href="${s[0]}.html" class="${page===s[0]?'active':''}" ${page===s[0]?'aria-current="page"':''}>${icon(s[1])}${tr(s[2],s[3])}</a>`).join('')}<a href="settings.html" class="${page==='settings'?'active':''}">${icon('settings')}${tr('الإعدادات','Settings')}</a></aside>`;}
function workspace(content){return `<div class="workspace">${sidebar()}<section>${content}</section></div>`;}
const btn=(label,action,id='',style='secondary small',ic='')=>`<button class="btn ${style}" data-action="${action}" data-id="${esc(id)}">${ic?icon(ic):''}${label}</button>`;
const empty=()=>`<div class="empty">${icon('search')}${tr('لا توجد نتائج مطابقة. جرّب تغيير البحث أو التصفية.','No matching results. Try another search or filter.')}</div>`;
const notice=(ar,en)=>`<div class="notice">${icon('info')}<span>${tr(ar,en)}</span></div>`;
const searchBox=(placeholder)=>`<div class="search">${icon('search')}<label class="screen-reader" for="search-input">${placeholder}</label><input id="search-input" type="search" placeholder="${placeholder}" value="${esc(query)}"></div>`;
function filters(items){return `<div class="filters">${items.map(([key,ar,en])=>`<button class="filter ${filter===key?'active':''}" data-action="filter" data-id="${key}" aria-pressed="${filter===key}">${tr(ar,en)}</button>`).join('')}</div>`;}
function serviceCards(){return services.filter(s=>(filter==='all'||s[6]===filter)&&(tr(s[2],s[3])+' '+tr(s[4],s[5])).toLowerCase().includes(query.toLowerCase())).map(s=>`<a class="service-card ${s[0]==='dashboard'?'featured':''}" href="${s[0]}.html"><span class="service-number">${String(services.indexOf(s)+1).padStart(2,'0')}</span>${icon(s[1])}<h3>${tr(s[2],s[3])}</h3><p>${tr(s[4],s[5])}</p><span class="service-arrow">${icon('arrow','direction-arrow')}</span></a>`).join('')||empty();}
function home(){return `<div class="toolbar">${searchBox(tr('ابحث عن خدمة...','Search for a service...'))}${filters([['all','جميع الخدمات','All services'],['training','التدريب','Training'],['my','خدمات المستفيد','My services']])}</div><div class="service-grid" id="results">${serviceCards()}</div><section class="home-section"><div class="section-head"><div><h2>${tr('برامج قادمة','Upcoming programs')}</h2><p>${tr('فرص جديدة لتطوير المعرفة والمهارات القانونية','New opportunities to develop your legal expertise')}</p></div><a class="text-link" href="programs.html">${tr('جميع البرامج','View all programs')}${icon('arrow','direction-arrow')}</a></div><div class="program-grid">${state.programs.filter(p=>p.status==='open').slice(0,3).map(programCard).join('')}</div></section><div class="intro-strip"><div><h3>${tr('ابدأ رحلتك التدريبية مع المعهد','Start your training journey')}</h3><p>${tr('اختر البرنامج المناسب، وقدّم ترشيحك، وتابع طلبك من مكان واحد.','Choose your program, submit a nomination and track it in one place.')}</p></div><a href="programs.html" class="btn">${tr('استعراض البرامج','Explore programs')}${icon('arrow','direction-arrow')}</a></div>`;}
function programCard(p){return `<article class="program-card"><div style="display:flex;justify-content:space-between;gap:10px"><span class="category">${category(p.category)}</span>${badge(p.status)}</div><h3><a href="program.html?id=${p.id}">${esc(text(p))}</a></h3><p class="description">${esc(text(p,'description'))}</p><div class="program-meta"><span class="meta-item">${icon('calendar')}${date(p.start)}</span><span class="meta-item">${icon('clock')}${num(p.hours)} ${tr('ساعة','hours')}</span></div><div class="program-footer"><span>${p.status==='open'?`${num(Math.max(0,p.seats-p.registered))} ${tr('مقاعد متاحة','seats available')}`:`<span class="program-code">${p.id}</span>`}</span><a class="text-link" href="program.html?id=${p.id}">${tr('التفاصيل','Details')}${icon('arrow','direction-arrow')}</a></div></article>`;}
function programResults(){const results=state.programs.filter(p=>(filter==='all'||p.status===filter)&&(text(p)+' '+p.id+' '+category(p.category)).toLowerCase().includes(query.toLowerCase()));return results.map(programCard).join('')||empty();}
function programs(){return `<div class="section-head"><div><h2>${tr('دليل البرامج التدريبية','Training program directory')}</h2><p>${tr('برامج متخصصة لبناء الكفاءات القضائية والقانونية','Specialist programs for judicial and legal professionals')}</p></div>${btn(tr('إنشاء برنامج','Create program'),'new-program','','','plus')}</div><div class="toolbar">${searchBox(tr('ابحث بالاسم أو رقم البرنامج...','Search by name or program ID...'))}${filters([['all','الكل','All'],['open','متاح','Open'],['pending','قيد الاعتماد','Pending'],['completed','مكتمل','Completed']])}</div><div class="program-grid" id="results">${programResults()}</div>`;}
function stats(items){return `<div class="stats">${items.map(([n,ar,en,ic,subAr,subEn])=>`<div class="stat"><div class="stat-top"><span>${tr(ar,en)}</span>${icon(ic)}</div><strong>${n}</strong><small>${tr(subAr||'بيانات النموذج التجريبي',subEn||'Prototype data')}</small></div>`).join('')}</div>`;}
function dashboard(){const pending=state.applications.filter(a=>a.status==='pending').length;return `<div class="section-head"><div><h2>${tr('مرحبًا بك في بوابة المعهد','Welcome to your institute portal')}</h2><p>${tr(...roles[role])} · ${tr('أكتوبر ٢٠٢٦','October 2026')}</p></div><a href="programs.html" class="btn">${icon('plus')}${tr('إدارة البرامج','Manage programs')}</a></div>${stats([[num(state.programs.length),'البرامج التدريبية','Training programs','programs'],[num(pending),'ترشيحات بانتظارك','Pending nominations','applications'],[num(state.programs.reduce((a,p)=>a+p.registered,0)),'المشاركون المسجلون','Registered participants','trainers'],[amount(state.expenses.reduce((a,e)=>a+e.amount,0)),'إجمالي المصروفات','Total expenses','finance']])}<div class="grid-two"><div class="panel"><div class="section-head"><h2>${tr('الجدول القادم','Coming up')}</h2><a href="schedule.html" class="text-link">${tr('عرض الكل','View all')}</a></div>${state.programs.filter(p=>p.status==='open').slice(0,3).map(p=>`<a href="program.html?id=${p.id}" class="calendar-row"><div class="date-tile"><b>${num(p.start.slice(-2))}</b><small>${new Intl.DateTimeFormat(lang==='ar'?'ar-BH':'en',{month:'short'}).format(new Date(p.start+'T12:00:00'))}</small></div><div><h3>${esc(text(p))}</h3><p>${esc(text(p,'room'))} · ${num(p.hours)} ${tr('ساعة تدريبية','training hours')}</p></div></a>`).join('')}</div><div class="panel"><h2>${tr('آخر الأنشطة','Recent activity')}</h2>${(state.activities.length?state.activities:[{ar:'تحتاج ترشيحات جديدة إلى المراجعة والاعتماد',en:'New nominations are ready for review'},{ar:'اكتمل برنامج أصول المرافعات وصياغة الأحكام',en:'Court Procedures & Judgment Writing completed'},{ar:'طلب مستحقات المدرب بانتظار المراجعة المالية',en:'Trainer payment is awaiting financial review'}]).slice(0,4).map(a=>`<div class="activity"><span class="dot"></span><div><p>${esc(text(a))}</p><small>${a.time?tr('نشاط محفوظ في هذه النسخة','Saved in this prototype'):tr('سجل توضيحي','Sample activity')}</small></div></div>`).join('')}</div></div><div class="panel"><div class="section-head"><h2>${tr('طلبات تحتاج إلى إجراء','Requests needing attention')}</h2><a class="text-link" href="applications.html">${tr('إدارة الترشيحات','Manage nominations')}</a></div>${applicationTable(state.applications.filter(a=>a.status==='pending'))}</div>`;}
function applicationTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${[tr('رقم الطلب','Request'),tr('المتدرب / الجهة','Trainee / organization'),tr('البرنامج','Program'),tr('الحالة','Status'),tr('الإجراء','Action')].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${rows.map(a=>`<tr><td><span class="program-code">${a.id}</span><span class="sub">${date(a.date)}</span></td><td><strong>${esc(text(a))}</strong><span class="sub">${esc(text(a,'org'))}</span></td><td><a href="program.html?id=${a.program}">${esc(text(state.programs.find(p=>p.id===a.program)||{ar:a.program,en:a.program}))}</a></td><td>${badge(a.status)}</td><td><div class="table-actions">${a.status==='pending'||a.status==='waiting'?btn(tr('اعتماد','Approve'),'approve-app',a.id,'small')+btn(tr('رفض','Reject'),'reject-app',a.id,'danger small'):btn(tr('عرض','View'),'view-app',a.id)}</div></td></tr>`).join('')}</tbody></table></div>`:empty();}
function applicationResults(){return applicationTable(state.applications.filter(a=>(filter==='all'||a.status===filter)&&(text(a)+' '+a.id+' '+text(a,'org')).toLowerCase().includes(query.toLowerCase())));}
function applications(){return `<div class="section-head"><div><h2>${tr('الترشيحات وطلبات التسجيل','Nominations & registrations')}</h2><p>${tr('اعتماد المشاركين وإدارة قوائم الانتظار','Approve participants and manage waiting lists')}</p></div>${btn(tr('ترشيح جديد','New nomination'),'nominate','','','plus')}</div><div class="toolbar">${searchBox(tr('ابحث عن متدرب أو طلب...','Search for a trainee or request...'))}${filters([['all','الكل','All'],['pending','قيد المراجعة','Pending'],['approved','معتمد','Approved'],['waiting','الانتظار','Waiting']])}</div><div class="panel" id="results">${applicationResults()}</div>`;}
function getProgram(){return state.programs.find(p=>p.id===new URLSearchParams(location.search).get('id'))||state.programs[0];}
function detail(){const p=getProgram(),trainer=state.trainers.find(t=>t.id===p.trainer)||state.trainers[0];let body='';if(activeTab==='overview')body=`<div class="detail-grid"><div><h3>${tr('عن البرنامج','About this program')}</h3><p>${esc(text(p,'description'))}</p><h3>${tr('مخرجات التعلّم','Learning outcomes')}</h3><ul class="check-list">${[tr('تطبيق المبادئ القانونية على حالات عملية','Apply legal principles to practical cases'),tr('تحليل المسائل وصياغة حلول قانونية واضحة','Analyze issues and develop clear legal solutions'),tr('تبادل الخبرات من خلال التمارين والنقاش','Exchange expertise through exercises and discussion')].map(s=>`<li>${icon('check')}${s}</li>`).join('')}</ul></div><aside class="info-box"><h3>${tr('متطلبات المشاركة','Participation requirements')}</h3><p>${tr('للعاملين في المجال القضائي والقانوني والمرشحين من الجهات المعنية.','For legal and judicial professionals and nominated organization representatives.')}</p><p>${tr('نسبة الحضور المطلوبة','Required attendance')}: ${num(state.settings.attendance)}%</p><p>${tr('درجة الاجتياز','Passing grade')}: ${num(state.settings.passing)}%</p><p>${tr('الشهادة: اجتياز / مشاركة','Award: completion / attendance')}</p></aside></div>`;
 if(activeTab==='agenda')body=`<div class="table-wrap"><table><thead><tr><th>${tr('اليوم','Day')}</th><th>${tr('الوقت','Time')}</th><th>${tr('الموضوع','Topic')}</th><th>${tr('المدرب','Trainer')}</th></tr></thead><tbody>${[[tr('الأول','One'),tr('المفاهيم والأسس القانونية','Legal concepts and foundations')],[tr('الثاني','Two'),tr('ورش عمل وحالات تطبيقية','Workshops and practical cases')],[tr('الثالث','Three'),tr('مشروع تطبيقي وتقييم ختامي','Applied project and final assessment')]].map(([day,topic])=>`<tr><td>${day}</td><td dir="ltr">09:00 – 15:00</td><td>${topic}</td><td>${esc(text(trainer))}</td></tr>`).join('')}</tbody></table></div>`;
 if(activeTab==='materials')body=`${notice('الملفات التالية أمثلة توضيحية، ويمكن إضافة مرفقات محلية صغيرة للتجربة.','These are sample resources. You can add small local attachments for review.')}<div class="activity">${icon('file')}<div style="flex:1"><p>${tr('دليل المشارك — نموذج توضيحي','Participant guide — sample')}</p><small>HTML · ${tr('قابل للتنزيل','Downloadable')}</small></div>${btn(tr('تنزيل','Download'),'sample-material',p.id,'secondary small','download')}</div>${state.materials.filter(m=>m.program===p.id).map(m=>`<div class="activity">${icon('file')}<div style="flex:1">${esc(m.name)}</div>${btn(tr('تنزيل','Download'),'download-material',m.id)}</div>`).join('')}<div style="margin-top:20px">${btn(tr('إضافة مادة تدريبية','Add training material'),'upload-material',p.id,'secondary','plus')}</div>`;
 if(activeTab==='approval')body=`<h3>${tr('مسار اعتماد البرنامج','Program approval workflow')}</h3><div class="flow">${[[tr('إعداد المنسق','Coordinator')],[tr('رئيس التدريب','Head of training')],[tr('مدير المعهد','Institute director')],[tr('جاهز للتنفيذ','Ready to deliver')]].map(([s],i)=>`<div class="flow-step ${i<p.approval?'done':i===p.approval?'current':''}"><i>${i<p.approval?'✓':i+1}</i>${s}</div>`).join('')}</div>${notice('الموافقة الخارجية مطلوبة عند تحديد الجهة الرئيسية في تصميم البرنامج. المسار المعروض مثال للموافقة الداخلية.','External approval applies when a main stakeholder is specified. This example shows the internal approval workflow.')} ${p.approval<3?btn(tr('اعتماد المرحلة التالية','Approve next stage'),'approve-program',p.id,'','check'):badge('approved')}`;
 return `<div class="panel"><div class="detail-header"><div><span class="program-code">${p.id}</span> · <span class="category">${category(p.category)}</span><h2>${esc(text(p))}</h2>${badge(p.status)}</div>${p.status==='open'?btn(tr('التسجيل في البرنامج','Register for program'),'nominate',p.id,'','plus'):''}</div><div class="detail-facts"><div><small>${tr('تاريخ البدء','Start date')}</small><strong>${date(p.start)}</strong></div><div><small>${tr('مدة البرنامج','Duration')}</small><strong>${num(p.hours)} ${tr('ساعة تدريبية','training hours')}</strong></div><div><small>${tr('المكان','Venue')}</small><strong>${esc(text(p,'room'))}</strong></div><div><small>${tr('المدرب','Trainer')}</small><strong>${esc(text(trainer))}</strong></div></div><div class="tabs" role="tablist">${[['overview','نظرة عامة','Overview'],['agenda','الجدول التفصيلي','Agenda'],['materials','المواد التدريبية','Materials'],['approval','الاعتمادات','Approvals']].map(([k,ar,en])=>`<button role="tab" aria-selected="${activeTab===k}" class="tab ${activeTab===k?'active':''}" data-action="tab" data-id="${k}">${tr(ar,en)}</button>`).join('')}</div><div role="tabpanel">${body}</div></div>`;}
function schedule(){const monthLabel=new Intl.DateTimeFormat(lang==='ar'?'ar-BH':'en',{month:'long',year:'numeric'}).format(new Date(2026,calendarMonth-1,1));const rows=state.programs.filter(p=>Number(p.start.slice(5,7))===calendarMonth).sort((a,b)=>a.start.localeCompare(b.start));return `<div class="section-head"><div><h2>${monthLabel}</h2><p>${tr('جدول الدورات والقاعات التدريبية','Course and training room schedule')}</p></div><div style="display:flex;gap:7px">${btn(tr('السابق','Previous'),'month-prev')}${btn(tr('التالي','Next'),'month-next')}</div></div><div class="panel">${rows.length?rows.map(p=>`<div class="calendar-row"><div class="date-tile"><b>${num(p.start.slice(-2))}</b><small>${tr('أكتوبر','Oct').replace(tr('أكتوبر','Oct'),new Intl.DateTimeFormat(lang==='ar'?'ar-BH':'en',{month:'short'}).format(new Date(p.start+'T12:00:00')))}</small></div><div style="flex:1"><h3><a href="program.html?id=${p.id}">${esc(text(p))}</a></h3><p>${date(p.start)} — ${date(p.end)} · ${esc(text(p,'room'))}</p><div style="margin-top:8px">${badge(p.status)}</div></div><a class="btn secondary small" href="program.html?id=${p.id}">${tr('التفاصيل','Details')}</a></div>`).join(''):empty()}</div>`;}
function trainers(){return `<div class="section-head"><div><h2>${tr('دليل المدربين','Trainer directory')}</h2><p>${tr('الخبرات المعتمدة والمواد التدريبية','Trainer expertise and program materials')}</p></div>${btn(tr('إضافة مدرب','Add trainer'),'new-trainer','','','plus')}</div><div class="program-grid">${state.trainers.map(t=>`<article class="trainer-card"><div class="avatar">${esc(text(t,'initials'))}</div><h3>${esc(text(t))}</h3><p>${esc(text(t,'specialty'))}</p><div class="trainer-foot"><span>${num(t.courses)} ${tr('برامج','programs')}</span><span>★ ${num(t.rating)} / 5</span></div><div style="margin-top:15px">${btn(tr('عرض الملف والمواد','Profile & materials'),'trainer',t.id,'secondary small')}</div></article>`).join('')}</div>`;}
function attendance(){const key=selectedProgram+'|'+attendanceDate;const today=state.attendance[key]||{};return `<div class="section-head"><div><h2>${tr('سجل الحضور اليومي','Daily attendance register')}</h2><p>${tr('تسجيل الحضور وتوثيق التعديلات','Record participation and justify changes')}</p></div>${btn(tr('تصدير السجل','Export register'),'export-attendance','','secondary','download')}</div><div class="panel"><div class="form-grid"><div class="field"><label for="attendance-program">${tr('البرنامج','Program')}</label><select id="attendance-program">${state.programs.map(p=>`<option value="${p.id}" ${selectedProgram===p.id?'selected':''}>${esc(text(p))}</option>`).join('')}</select></div><div class="field"><label for="attendance-date">${tr('التاريخ','Date')}</label><input id="attendance-date" type="date" value="${attendanceDate}"></div></div><form id="checkin-form" class="toolbar" style="margin-top:20px"><div class="search"><label class="screen-reader" for="demo-id">${tr('معرّف المتدرب','Trainee ID')}</label><input id="demo-id" name="trainee" placeholder="${tr('أدخل معرّفًا تجريبيًا مثل DEMO-101','Enter a demo ID, e.g. DEMO-101')}" required style="padding-inline-start:15px"></div><button class="btn">${icon('check')}${tr('تسجيل الحضور','Check in')}</button></form>${notice('قائمة المشاركين للتجربة مشتركة بين البرامج. استخدم المعرفات المعروضة، ولا تدخل أرقام هوية حقيقية.','This shared sample roster is for demonstration. Use the displayed IDs, not real identity numbers.')}<div class="table-wrap"><table><thead><tr><th>${tr('المتدرب','Trainee')}</th><th>${tr('المعرف التجريبي','Demo ID')}</th><th>${tr('حضور اليوم','Today’s attendance')}</th><th>${tr('الإجراء','Action')}</th></tr></thead><tbody>${state.trainees.map(t=>`<tr><td>${esc(text(t))}</td><td dir="ltr">${t.id}</td><td>${badge(today[t.id]?.status||'unmarked')}</td><td><div class="table-actions">${btn(tr('حاضر','Present'),'mark-present',t.id)}${btn(tr('تعديل','Adjust'),'adjust-attendance',t.id)}</div></td></tr>`).join('')}</tbody></table></div></div>`;}
function assessments(){return `<div class="section-head"><div><h2>${tr('نتائج أصول المرافعات وصياغة الأحكام','Court Procedures & Judgment Writing results')}</h2><p>JLSI-024 · ${tr('الاختبار النهائي والتكليف التطبيقي','Final exam and applied assignment')}</p></div>${btn(tr('تنزيل نموذج الاختبار','Download sample exam'),'sample-exam','','secondary','download')}</div>${notice('درجة الاجتياز تُحسب من متوسط الاختبار والتكليف. هذا نموذج مبسط قابل للتطوير وفق أوزان التقييم المعتمدة.','The pass grade uses the mean of exam and assignment scores. This simplified model can be extended with approved weights.')}<form id="grades-form" class="panel"><div class="table-wrap"><table><thead><tr><th>${tr('المتدرب','Trainee')}</th><th>${tr('الاختبار / ١٠٠','Exam / 100')}</th><th>${tr('التكليف / ١٠٠','Assignment / 100')}</th><th>${tr('المتوسط المحفوظ','Saved average')}</th></tr></thead><tbody>${state.trainees.map(t=>`<tr><td>${esc(text(t))}</td><td><input aria-label="${tr('درجة الاختبار لـ','Exam grade for')} ${esc(text(t))}" class="input-small" name="exam-${t.id}" type="number" min="0" max="100" required value="${t.exam}"></td><td><input aria-label="${tr('درجة التكليف لـ','Assignment grade for')} ${esc(text(t))}" class="input-small" name="assignment-${t.id}" type="number" min="0" max="100" required value="${t.assignment}"></td><td><strong>${num((t.exam+t.assignment)/2)}%</strong></td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="btn">${icon('check')}${tr('حفظ الدرجات','Save grades')}</button></div></form>`;}
function evaluations(){return `<div class="section-head"><div><h2>${tr('تقييم البرنامج التدريبي','Evaluate your training program')}</h2><p>${tr('رأيك يساعدنا على تطوير تجربة التدريب','Your feedback helps improve the training experience')}</p></div><span class="badge">${num(state.evaluations.length)} ${tr('استجابات تجريبية','demo responses')}</span></div><form id="evaluation-form" class="panel"><div class="form-grid" style="margin-bottom:25px">${selectField('program',tr('البرنامج','Program'),state.programs.map(p=>[p.id,text(p)]))}${selectField('type',tr('نوع التقييم','Evaluation type'),[['course',tr('تقييم نهاية البرنامج','End of program')],['impact',tr('أثر التدريب بعد ٣ أشهر','Impact after 3 months')],['annual',tr('تقييم تجربة المعهد','Institute experience')]])}</div>${[[tr('مدى تحقيق البرنامج لأهدافه','Achievement of learning objectives')],[tr('جودة المحتوى والمواد التدريبية','Quality of content and materials')],[tr('فاعلية المدرب وأساليب التدريب','Trainer effectiveness and teaching methods')],[tr('قابلية تطبيق المهارات في العمل','Applicability of skills at work')]].map(([q],i)=>`<fieldset class="question" style="border:0;padding:0"><legend style="margin-bottom:10px;font-size:14px">${q}</legend><div class="rating-group">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="q${i}" value="${n}" required aria-label="${num(n)} ${tr('من ٥','out of 5')}"><span>${num(n)}</span></label>`).join('')}</div><div class="grade-hint">${tr('١ = غير راضٍ • ٥ = راضٍ جدًا','1 = dissatisfied • 5 = very satisfied')}</div></fieldset>`).join('')}${field('comments',tr('ملاحظات ومقترحات','Comments & suggestions'),'textarea',false)}<div class="form-actions"><button class="btn">${tr('إرسال التقييم','Submit evaluation')}${icon('check')}</button></div></form>`;}
const eligible=t=>t.attendance>=state.settings.attendance&&(t.exam+t.assignment)/2>=state.settings.passing;
function certificates(){return `<div class="section-head"><div><h2>${tr('شهادات المتدربين','Trainee certificates')}</h2><p>${tr('أصول المرافعات وصياغة الأحكام','Court Procedures & Judgment Writing')} · JLSI-024</p></div></div>${notice(`معيار الاجتياز في النموذج: حضور ${state.settings.attendance}% فأكثر، ومتوسط درجات ${state.settings.passing}% فأكثر.`,`Prototype completion criteria: attendance ≥ ${state.settings.attendance}% and average grade ≥ ${state.settings.passing}%.`)}<div class="panel"><div class="table-wrap"><table><thead><tr>${[tr('المتدرب','Trainee'),tr('الحضور','Attendance'),tr('النتيجة','Average'),tr('الشهادة','Award'),tr('الإجراء','Action')].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${state.trainees.map(t=>`<tr><td>${esc(text(t))}</td><td>${num(t.attendance)}%</td><td>${num((t.exam+t.assignment)/2)}%</td><td>${eligible(t)?badge('approved'):`<span class="badge pending">${tr('لم يستوفِ الشروط','Criteria not met')}</span>`}</td><td>${eligible(t)?btn(tr('عرض وطباعة','View & print'),'certificate',t.id,'secondary small','certificates'):btn(tr('عرض السبب','View reason'),'certificate-reason',t.id)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function finance(){return `<div class="section-head"><div><h2>${tr('مستحقات البرامج التدريبية','Training program payments')}</h2><p>${tr('اعتماد المصروفات ومتابعة حالة الصرف','Approve expenses and track payment status')}</p></div>${btn(tr('إضافة مصروف','Add expense'),'new-expense','','','plus')}</div>${stats([[amount(state.expenses.reduce((a,e)=>a+e.amount,0)),'إجمالي المصروفات','Total expenses','finance'],[amount(state.expenses.filter(e=>e.status==='pending').reduce((a,e)=>a+e.amount,0)),'بانتظار الاعتماد','Pending approval','clock'],[amount(state.expenses.filter(e=>e.status==='approved').reduce((a,e)=>a+e.amount,0)),'جاهز للصرف','Ready for payment','applications'],[amount(state.expenses.filter(e=>e.status==='paid').reduce((a,e)=>a+e.amount,0)),'تم الصرف','Paid','check']])}<div class="panel"><div class="table-wrap"><table><thead><tr><th>${tr('الطلب','Request')}</th><th>${tr('بيان المصروف','Description')}</th><th>${tr('المبلغ','Amount')}</th><th>${tr('الحالة','Status')}</th><th>${tr('الإجراء','Action')}</th></tr></thead><tbody>${state.expenses.map(e=>`<tr><td class="program-code">${e.id}</td><td>${esc(text(e))}<span class="sub">${e.program}</span></td><td>${amount(e.amount)}</td><td>${badge(e.status)}</td><td>${e.status==='pending'?btn(tr('اعتماد','Approve'),'approve-expense',e.id,'small'):e.status==='approved'?btn(tr('تأكيد الصرف','Confirm payment'),'pay-expense',e.id,'secondary small'):icon('check')}</td></tr>`).join('')}</tbody></table></div></div>${notice('عمليات الاعتماد والصرف هنا محاكاة للمراجعة، ولا تنفّذ تحويلات أو ترسل طلبات إلى وزارة العدل.','Approval and payment actions are simulated. No funds are transferred and no requests are sent to the Ministry of Justice.')}`;}
function reports(){const values=state.evaluations.flatMap(e=>e.scores);const avg=values.length?num(values.reduce((a,b)=>a+b,0)/values.length):'—';return `<div class="section-head"><div><h2>${tr('مؤشرات الأداء التدريبي','Training performance overview')}</h2><p>${tr('ملخص البرامج والتقييم والتكاليف','Programs, feedback and cost summary')}</p></div>${btn(tr('تصدير CSV','Export CSV'),'export-report','','','download')}</div>${stats([[num(state.programs.length),'البرامج','Programs','programs'],[num(state.applications.length),'الترشيحات','Nominations','applications'],[avg,'متوسط التقييم / ٥','Average rating / 5','star'],[num(state.trainees.filter(eligible).length),'المستحقون للشهادات','Eligible for certificates','certificates']])}<div class="grid-two"><div class="panel"><h2>${tr('التسجيل حسب البرنامج','Registration by program')}</h2>${state.programs.map(p=>`<div style="margin:15px 0"><div style="display:flex;justify-content:space-between;font-size:11px"><span>${esc(text(p))}</span><b>${num(p.registered)} / ${num(p.seats)}</b></div><div class="progress"><span style="width:${Math.min(100,p.registered/p.seats*100)}%"></span></div></div>`).join('')}</div><div class="panel"><h2>${tr('استيفاء شروط الشهادات','Certificate eligibility')}</h2><div class="donut" style="background:conic-gradient(var(--ink) 0 ${state.trainees.filter(eligible).length/state.trainees.length*100}%,#edf1f1 0)"><div><strong>${num(state.trainees.filter(eligible).length/state.trainees.length*100)}%</strong><small>${tr('مستوفون للشروط','Eligible trainees')}</small></div></div><div class="legend"><span><i></i>${tr('مستوفٍ','Eligible')}</span><span><i style="background:#edf1f1"></i>${tr('غير مستوفٍ','Not eligible')}</span></div><p style="font-size:12px;color:var(--muted);text-align:center">JLSI-024 · ${tr('عينة المتدربين التجريبية','Sample trainee roster')}</p></div></div>`;}
function media(){return `<div class="section-head"><div><h2>${tr('توثيق فعاليات المعهد','Institute event archive')}</h2><p>${tr('الصور والأخبار والوثائق المرتبطة بالبرامج','Photos, news and program documents')}</p></div>${btn(tr('إضافة مادة إعلامية','Add media'),'new-media','','','plus')}</div><div class="media-list">${state.media.map(m=>`<article class="media-item"><div class="media-preview">${m.data?.startsWith('data:image/')?`<img src="${esc(m.data)}" alt="${esc(m.title)}">`:icon('file')}</div><div class="media-caption"><h3>${esc(m.title)}</h3><small>${esc(m.program)} · ${esc(m.name)}</small><div style="margin-top:10px">${btn(tr('تنزيل المرفق','Download attachment'),'download-media',m.id)}</div></div></article>`).join('')}<article class="media-item"><div class="media-preview">${icon('scales')}</div><div class="media-caption"><h3>${tr('اختتام برنامج أصول المرافعات','Court Procedures program completed')}</h3><small>${tr('مادة خبرية توضيحية','Sample news item')} · 8 Oct 2026</small><div style="margin-top:10px">${btn(tr('قراءة الخبر','Read story'),'news')}</div></div></article></div>`;}
function settings(){return `<div class="section-head"><div><h2>${tr('تفضيلات النظام','System preferences')}</h2><p>${tr('إعدادات النسخة التجريبية على هذا المتصفح','Prototype settings in this browser')}</p></div></div><form id="settings-form" class="panel"><h3>${tr('معايير استحقاق الشهادة','Certificate eligibility criteria')}</h3><div class="form-grid">${field('attendance',tr('الحد الأدنى للحضور (%)','Minimum attendance (%)'),'number',true,state.settings.attendance,'min="0" max="100"')}${field('passing',tr('الحد الأدنى للاجتياز (%)','Minimum passing grade (%)'),'number',true,state.settings.passing,'min="0" max="100"')}</div><label class="checkbox-line"><input name="largeText" type="checkbox" ${state.settings.largeText?'checked':''}>${tr('تكبير النص لتحسين القراءة','Larger text for easier reading')}</label><div class="form-actions"><button class="btn">${tr('حفظ الإعدادات','Save settings')}</button></div></form><div class="panel"><h3>${tr('البيانات التجريبية','Demonstration data')}</h3><p>${tr('تُحفظ تغييراتك في المتصفح الحالي. يمكنك إعادة النموذج إلى بياناته الأصلية في أي وقت.','Your changes are stored in this browser. You can restore the original sample data at any time.')}</p>${btn(tr('إعادة ضبط البيانات','Reset sample data'),'reset','','danger')}</div>`;}
function renderPage(){const renderers={home,programs,dashboard,applications,program:detail,schedule,trainers,attendance,assessments,evaluations,certificates,finance,reports,media,settings};const content=(renderers[page]||home)();$('#content').innerHTML=['home','programs','program'].includes(page)?content:workspace(content);}
function field(name,label,type='text',required=true,value='',attrs=''){const id='field-'+name;return `<div class="field ${type==='textarea'?'full':''}"><label for="${id}">${label}${required?' <span style="color:var(--gold)">*</span>':''}</label>${type==='textarea'?`<textarea id="${id}" name="${name}" ${required?'required':''} maxlength="1500">${esc(value)}</textarea>`:`<input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${attrs} ${type==='text'?'maxlength="160"':''}>`}</div>`;}
function selectField(name,label,options,value=''){return `<div class="field"><label for="field-${name}">${label} <span style="color:var(--gold)">*</span></label><select id="field-${name}" name="${name}" required>${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
function actions(label=tr('حفظ','Save')){return `<div class="form-actions">${btn(tr('إلغاء','Cancel'),'close-modal')}<button class="btn" type="submit">${label}</button></div>`;}
function modal(title,body){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close-btn" data-action="close-modal" aria-label="${tr('إغلاق','Close')}">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';$('#app').inert=true;setTimeout(()=>$('.modal input,.modal select,.modal textarea,.modal button')?.focus(),30);}
function closeModal(){const wasOpen=!!$('.modal');$('#modal-root').innerHTML='';document.body.style.overflow='';$('#app').inert=false;if(wasOpen&&modalFocus?.isConnected)modalFocus.focus();}
function newProgram(){modal(tr('إنشاء برنامج تدريبي','Create a training program'),`<form id="program-form"><div class="form-grid">${field('ar',tr('اسم البرنامج بالعربية','Program name in Arabic'))}${field('en','Program name in English')}${selectField('category',tr('المجال','Category'),['law','judicial','rights'].map(c=>[c,category(c)]))}${selectField('trainer',tr('المدرب','Trainer'),state.trainers.map(t=>[t.id,text(t)]))}${field('start',tr('تاريخ البدء','Start date'),'date',true,'2026-11-15')}${field('end',tr('تاريخ الانتهاء','End date'),'date',true,'2026-11-17')}${field('hours',tr('عدد الساعات','Training hours'),'number',true,18,'min="1" max="500"')}${field('seats',tr('عدد المقاعد','Seats'),'number',true,25,'min="1" max="500"')}${field('descriptionAr',tr('وصف البرنامج بالعربية','Program description in Arabic'),'textarea')}${field('descriptionEn','Program description in English','textarea')}</div>${actions(tr('حفظ وإرسال للاعتماد','Save & submit for approval'))}</form>`);}
function nomination(id){const available=state.programs.filter(p=>p.status==='open');if(!available.length){toast(tr('لا توجد برامج متاحة حاليًا.','No open programs available.'));return;}modal(tr('تقديم ترشيح جديد','Submit a nomination'),`<form id="nomination-form">${notice('استخدم بيانات افتراضية فقط. الطلب سيُحفظ في هذا المتصفح ولن يُرسل إلى المعهد.','Use fictional information only. This request stays in this browser and is not sent to the institute.')}<div class="form-grid">${selectField('program',tr('البرنامج التدريبي','Training program'),available.map(p=>[p.id,text(p)]),id)}${selectField('type',tr('نوع الترشيح','Nomination type'),[['organization',tr('ترشيح من جهة','Organization nomination')],['individual',tr('تسجيل فردي','Individual registration')]])}${field('ar',tr('اسم المتدرب بالعربية','Trainee name in Arabic'))}${field('en','Trainee name in English')}${field('orgAr',tr('اسم الجهة بالعربية','Organization name in Arabic'))}${field('orgEn','Organization name in English')}${field('demoId',tr('المعرّف التجريبي','Demo identifier'),'text',true,'','pattern="DEMO-[A-Za-z0-9-]+" placeholder="DEMO-106" title="DEMO-106"')}</div><label class="checkbox-line"><input type="checkbox" required>${tr('راجعت متطلبات البرنامج وأؤكد الترشيح','I reviewed the program requirements and confirm this nomination')}</label>${actions(tr('إرسال الترشيح','Submit nomination'))}</form>`);}
function uploadForm(kind,id){modal(kind==='media'?tr('إضافة مادة إعلامية','Add media'):tr('إضافة مادة تدريبية','Add training material'),`<form id="upload-form" data-kind="${kind}"><div class="form-grid">${kind==='media'?field('title',tr('عنوان المادة','Title')):''}${selectField('program',tr('البرنامج','Program'),state.programs.map(p=>[p.id,text(p)]),id)}${field('file',tr('المرفق (حتى ٥٠٠ كيلوبايت)','Attachment (up to 500 KB)'),'file',true,'','accept=".pdf,.png,.jpg,.jpeg,.txt"')}</div><p>${tr('المرفقات محفوظة في هذا المتصفح فقط.','Attachments are stored only in this browser.')}</p>${actions()}</form>`);}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(name,rows){const sanitize=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download(name,'\uFEFF'+rows.map(r=>r.map(sanitize).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function certificate(t){if(!eligible(t))return;modal(tr('معاينة الشهادة','Certificate preview'),`<div class="certificate"><div class="brand-mark">${icon('scales')}</div><p>${tr('معهد الدراسات القضائية والقانونية','Judicial & Legal Studies Institute')}</p><div class="cert-title">${tr('شهادة اجتياز','Certificate of Completion')}</div><span class="demo-badge">${tr('نموذج تجريبي — غير صالح للاستخدام الرسمي','DEMONSTRATION — NOT AN OFFICIAL CERTIFICATE')}</span><p>${tr('يشهد المعهد بأن','This certifies that')}</p><h3>${esc(text(t))}</h3><p>${tr('قد اجتاز متطلبات البرنامج التدريبي','has successfully completed the requirements of')}</p><h2>${tr('أصول المرافعات وصياغة الأحكام','Court Procedures & Judgment Writing')}</h2><p>${tr('خلال الفترة من ٤ إلى ٨ أكتوبر ٢٠٢٦، بواقع ٢٤ ساعة تدريبية.','Held from 4 to 8 October 2026, totaling 24 training hours.')}</p><div class="cert-foot"><span>DEMO-CERT-${t.id}</span><span>${tr('نسخة توضيحية دون توقيع رسمي','Illustrative copy without official signature')}</span></div></div><div class="form-actions">${btn(tr('إغلاق','Close'),'close-modal')}${btn(tr('طباعة / حفظ PDF','Print / Save PDF'),'print','','','download')}</div>`);}
document.addEventListener('click',e=>{const node=e.target.closest('[data-action]');if(!node)return;e.preventDefault();const action=node.dataset.action,id=node.dataset.id;
 switch(action){
 case'language':lang=lang==='ar'?'en':'ar';try{localStorage.setItem(LANG,lang);}catch{}closeModal();shell();break;
 case'filter':filter=id;renderPage();break;
 case'tab':activeTab=id;renderPage();break;
 case'new-program':newProgram();break;
 case'nominate':nomination(id);break;
 case'close-modal':closeModal();break;
 case'approve-app':{const a=state.applications.find(a=>a.id===id),p=state.programs.find(p=>p.id===a.program);if(p.registered>=p.seats){a.status='waiting';save();renderPage();toast(tr('اكتملت المقاعد. أُضيف الطلب إلى قائمة الانتظار.','Program full. The request is now waitlisted.'));break;}a.status='approved';p.registered++;activity('اعتماد الترشيح '+a.id,'Nomination approved: '+a.id);renderPage();toast(tr('تم اعتماد الترشيح وحجز المقعد.','Nomination approved and seat reserved.'));break;}
 case'reject-app':modal(tr('رفض الترشيح','Reject nomination'),`<form id="reject-form" data-id="${id}">${field('reason',tr('سبب الرفض','Reason for rejection'),'textarea')}${actions(tr('تأكيد الرفض','Confirm rejection'))}</form>`);break;
 case'view-app':{const a=state.applications.find(a=>a.id===id);modal(tr('تفاصيل الطلب','Request details'),`<p class="program-code">${a.id}</p><h3>${esc(text(a))}</h3><p>${esc(text(a,'org'))}</p><p>${esc(text(state.programs.find(p=>p.id===a.program)))}</p>${badge(a.status)}${a.reason?`<p>${esc(a.reason)}</p>`:''}<div class="form-actions">${btn(tr('إغلاق','Close'),'close-modal')}</div>`);break;}
 case'approve-program':{const p=state.programs.find(p=>p.id===id);p.approval=Math.min(3,p.approval+1);if(p.approval===3)p.status='open';activity('تحديث اعتماد البرنامج '+p.id,'Program approval updated: '+p.id);renderPage();toast(tr('تم اعتماد المرحلة وتحديث مسار البرنامج.','Stage approved and workflow updated.'));break;}
 case'month-prev':calendarMonth=calendarMonth===1?12:calendarMonth-1;renderPage();break;
 case'month-next':calendarMonth=calendarMonth===12?1:calendarMonth+1;renderPage();break;
 case'new-trainer':modal(tr('إضافة مدرب','Add trainer'),`<form id="trainer-form"><div class="form-grid">${field('ar',tr('اسم المدرب بالعربية','Trainer name in Arabic'))}${field('en','Trainer name in English')}${field('specialtyAr',tr('التخصص بالعربية','Specialty in Arabic'))}${field('specialtyEn','Specialty in English')}</div>${actions()}</form>`);break;
 case'trainer':{const t=state.trainers.find(t=>t.id===id);modal(esc(text(t)),`<p>${esc(text(t,'specialty'))}</p><h3>${tr('البرامج والمواد المرتبطة','Assigned programs & materials')}</h3>${state.programs.filter(p=>p.trainer===id).map(p=>`<div class="activity"><a href="program.html?id=${p.id}">${esc(text(p))} ${icon('arrow','direction-arrow')}</a></div>`).join('')||`<p>${tr('لا توجد برامج مسندة بعد.','No assigned programs yet.')}</p>`}<div class="form-actions">${btn(tr('إغلاق','Close'),'close-modal')}</div>`);break;}
 case'mark-present':markAttendance(id,'present');break;
 case'adjust-attendance':modal(tr('تعديل سجل الحضور','Adjust attendance'),`<form id="adjust-form" data-id="${id}">${selectField('status',tr('حالة الحضور','Attendance status'),[['present',tr('حاضر','Present')],['absent',tr('غائب','Absent')]])}${field('reason',tr('مبرر التعديل','Reason for adjustment'),'textarea')}${actions()}</form>`);break;
 case'certificate':certificate(state.trainees.find(t=>t.id===id));break;
 case'certificate-reason':{const t=state.trainees.find(t=>t.id===id);modal(tr('معايير لم تُستوفَ','Unmet criteria'),`<p>${esc(text(t))}</p><ul>${t.attendance<state.settings.attendance?`<li>${tr('نسبة الحضور أقل من الحد المطلوب.','Attendance is below the required threshold.')}</li>`:''}${(t.exam+t.assignment)/2<state.settings.passing?`<li>${tr('متوسط الدرجات أقل من حد الاجتياز.','Average grade is below the passing threshold.')}</li>`:''}</ul><div class="form-actions">${btn(tr('إغلاق','Close'),'close-modal')}</div>`);break;}
 case'print':window.print();break;
 case'new-expense':modal(tr('إضافة مصروف','Add expense'),`<form id="expense-form"><div class="form-grid">${field('ar',tr('بيان المصروف بالعربية','Expense description in Arabic'))}${field('en','Expense description in English')}${selectField('program',tr('البرنامج','Program'),state.programs.map(p=>[p.id,text(p)]))}${field('amount',tr('المبلغ بالدينار البحريني','Amount in BHD'),'number',true,'','min="0.001" max="1000000" step="0.001"')}</div>${actions(tr('إرسال للمراجعة','Submit for review'))}</form>`);break;
 case'approve-expense':case'pay-expense':{const e=state.expenses.find(e=>e.id===id);e.status=action==='approve-expense'?'approved':'paid';activity('تحديث حالة طلب الصرف '+e.id,'Payment request updated: '+e.id);renderPage();toast(tr('تم تحديث حالة الطلب التجريبي.','Demo request status updated.'));break;}
 case'new-media':uploadForm('media');break;
 case'upload-material':uploadForm('material',id);break;
 case'download-media':case'download-material':{const item=(action==='download-media'?state.media:state.materials).find(m=>m.id===id);const a=document.createElement('a');a.href=item.data;a.download=item.name;document.body.append(a);a.click();a.remove();break;}
 case'news':modal(tr('اختتام برنامج أصول المرافعات','Court Procedures program completed'),`<p>${tr('محتوى توضيحي: اختتم المعهد البرنامج التدريبي بعد سلسلة من الورش التطبيقية والنقاشات القانونية. يتضمن هذا القسم أرشفة التغطيات الإعلامية المرتبطة بالبرامج.','Sample content: The institute concluded the training program following practical workshops and legal discussions. This section archives media coverage associated with training programs.')}</p><div class="form-actions">${btn(tr('إغلاق','Close'),'close-modal')}</div>`);break;
 case'sample-material':case'sample-exam':download(action==='sample-exam'?'sample-exam.html':'participant-guide.html',`<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><title>JLSI Demo</title><body style="font:20px/2 Arial;max-width:800px;margin:60px auto"><h1>${tr(action==='sample-exam'?'نموذج اختبار تدريبي':'دليل المشارك',action==='sample-exam'?'Sample assessment':'Participant guide')}</h1><p>${tr('وثيقة تجريبية للتوضيح فقط.','Demonstration document only.')}</p><h2>${tr('تمرين تطبيقي','Practical exercise')}</h2><p>${tr('حلّل نصًا قانونيًا مختارًا، وحدد المسألة القانونية واقترح صياغة بديلة مع بيان الأسباب.','Analyze a selected legal text, identify the legal issue and propose alternative wording with reasons.')}</p></body></html>`,'text/html;charset=utf-8');break;
 case'export-attendance':{const today=state.attendance[selectedProgram+'|'+attendanceDate]||{};csv('attendance-'+attendanceDate+'.csv',[[tr('المعرف','ID'),tr('الاسم','Name'),tr('البرنامج','Program'),tr('التاريخ','Date'),tr('الحالة','Status'),tr('المبرر','Reason')],...state.trainees.map(t=>[t.id,text(t),selectedProgram,attendanceDate,tr(...statusNames[today[t.id]?.status||'unmarked']),today[t.id]?.reason||''])]);break;}
 case'export-report':csv('jlsi-program-report.csv',[[tr('البرنامج','Program'),tr('الاسم','Name'),tr('البداية','Start'),tr('الساعات','Hours'),tr('المقاعد','Seats'),tr('المسجلون','Registered'),tr('الحالة','Status')],...state.programs.map(p=>[p.id,text(p),p.start,p.hours,p.seats,p.registered,tr(...statusNames[p.status])])]);break;
 case'reset':modal(tr('إعادة ضبط البيانات التجريبية؟','Reset sample data?'),`<p>${tr('ستُحذف التغييرات والمرفقات المحفوظة لهذا النموذج في المتصفح، وتعود السجلات الأصلية.','Your saved changes and attachments for this prototype will be removed and the original sample records restored.')}</p><div class="form-actions">${btn(tr('إلغاء','Cancel'),'close-modal')}${btn(tr('إعادة الضبط','Reset'),'confirm-reset','','danger')}</div>`);break;
 case'confirm-reset':state=clone(window.JLSI_SEED);save();closeModal();shell();toast(tr('أُعيدت البيانات الأصلية.','Original sample data restored.'));break;
 case'help':modal(tr('دليل تجربة النموذج','Prototype walkthrough'),`<ol><li>${tr('استعرض البرامج وافتح تفاصيل أحدها.','Browse programs and open a program’s details.')}</li><li>${tr('قدّم ترشيحًا جديدًا باستخدام بيانات افتراضية.','Submit a nomination using fictional information.')}</li><li>${tr('اعتمد الترشيح من صفحة الترشيحات والطلبات.','Approve it on the Nominations & requests page.')}</li><li>${tr('جرّب تسجيل الحضور وتعديل الدرجات.','Try attendance recording and grade entry.')}</li><li>${tr('اعرض شهادة مستحقة واطبعها أو احفظها PDF.','Preview an eligible certificate and print or save it as PDF.')}</li><li>${tr('بدّل اللغة أو دور العرض من أعلى الصفحة.','Change the language or preview role in the header.')}</li></ol><p>${tr('تبديل الدور يغيّر قائمة العرض فقط؛ لا يمثل تسجيل دخول أو صلاحيات أمنية حقيقية.','Role switching changes the navigation only; it is not real authentication or access control.')}</p>`);break;
 case'about':modal(tr('عن النموذج','About this prototype'),`<p>${tr('نموذج أولي تفاعلي يستند إلى وثيقتي متطلبات نظام إدارة التدريب وواجهات المستخدم للمعهد. التصميم مستلهم من بوابة خدمات وزارة الإسكان البحرينية.','An interactive prototype based on the institute’s training management requirements and interface documents. Its visual design is inspired by Bahrain’s housing services portal.')}</p><p>${tr('النسخة مبنية بصفحات HTML وCSS وJavaScript، وتستخدم بيانات افتراضية محفوظة في المتصفح. لا تتصل بأنظمة المعهد أو المفتاح الإلكتروني أو خدمات الدفع والرسائل.','Built with HTML, CSS and JavaScript, using fictional records stored in your browser. It is not connected to institute systems, eKey, payment or messaging services.')}</p><a class="text-link" href="https://services.housing.gov.bh/home" target="_blank" rel="noopener">${tr('الموقع المرجعي','Reference website')}${icon('arrow','direction-arrow')}</a>`);break;
 }
});
function markAttendance(id,status,reason=''){const key=selectedProgram+'|'+attendanceDate;state.attendance[key]||={};state.attendance[key][id]={status,reason};save();renderPage();toast(tr('تم حفظ سجل الحضور.','Attendance record saved.'));}
document.addEventListener('input',e=>{if(e.target.id==='search-input'){query=e.target.value;$('#results').innerHTML=page==='home'?serviceCards():page==='programs'?programResults():applicationResults();}});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){role=e.target.value;try{localStorage.setItem('jlsi-role',role);}catch{}renderPage();toast(tr('تم تغيير دور العرض التجريبي.','Demo preview role changed.'));}if(e.target.id==='attendance-program'){selectedProgram=e.target.value;renderPage();}if(e.target.id==='attendance-date'&&e.target.value){attendanceDate=e.target.value;renderPage();}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));
 if(f.id==='program-form'){if(d.end<d.start){f.elements.end.setCustomValidity(tr('تاريخ الانتهاء يجب ألا يسبق تاريخ البدء.','End date must not precede start date.'));f.elements.end.reportValidity();f.elements.end.oninput=()=>f.elements.end.setCustomValidity('');return;}const id='JLSI-'+String(Math.max(...state.programs.map(p=>Number(p.id.split('-')[1])))+1).padStart(3,'0');state.programs.unshift({...d,id,hours:Number(d.hours),seats:Number(d.seats),registered:0,approval:1,status:'pending',roomAr:'القاعة الرئيسية',roomEn:'Main training hall'});activity('إنشاء البرنامج '+id,'Program created: '+id);closeModal();filter='all';renderPage();toast(tr('حُفظ البرنامج وأُرسل للاعتماد.','Program saved and submitted for approval.'));}
 if(f.id==='nomination-form'){if(state.applications.some(a=>a.demoId===d.demoId&&a.program===d.program&&a.status!=='rejected')){toast(tr('يوجد طلب سابق لهذا المعرف في البرنامج نفسه.','This ID already has a request for the same program.'));return;}const id='REQ-'+String(Math.max(1042,...state.applications.map(a=>Number(a.id.split('-')[1])))+1);const p=state.programs.find(p=>p.id===d.program);state.applications.unshift({...d,id,status:p.registered>=p.seats?'waiting':'pending',date:'2026-10-14'});activity('استلام ترشيح جديد '+id,'New nomination received: '+id);closeModal();modal(tr('تم استلام الترشيح','Nomination received'),`<div class="success-box">${icon('check')} ${tr('حُفظ طلبك التجريبي بنجاح.','Your demonstration request has been saved.')}</div><p>${tr('رقم الطلب','Request number')}: <strong>${id}</strong></p><p>${tr('يمكنك متابعة حالته من صفحة الترشيحات والطلبات.','Track its status on the Nominations & requests page.')}</p><div class="form-actions"><a class="btn" href="applications.html">${tr('متابعة الطلب','Track request')}</a></div>`);}
 if(f.id==='reject-form'){state.applications.find(a=>a.id===f.dataset.id).status='rejected';state.applications.find(a=>a.id===f.dataset.id).reason=d.reason;activity('رفض الترشيح '+f.dataset.id,'Nomination rejected: '+f.dataset.id);closeModal();renderPage();toast(tr('حُفظ قرار الرفض وسببه.','Rejection and reason saved.'));}
 if(f.id==='trainer-form'){state.trainers.push({...d,id:'t'+Date.now(),initialsAr:d.ar.split(' ').slice(0,2).map(s=>s[0]).join(' '),initialsEn:d.en.split(' ').slice(0,2).map(s=>s[0]).join(''),courses:0,rating:0});save();closeModal();renderPage();toast(tr('أُضيف المدرب إلى الدليل.','Trainer added to the directory.'));}
 if(f.id==='checkin-form'){const id=d.trainee.trim().toUpperCase();if(!state.trainees.some(t=>t.id===id)){toast(tr('لم يُعثر على المعرف في القائمة التجريبية.','ID not found in the demo roster.'));return;}markAttendance(id,'present');}
 if(f.id==='adjust-form'){const id=f.dataset.id;closeModal();markAttendance(id,d.status,d.reason);}
 if(f.id==='grades-form'){state.trainees.forEach(t=>{t.exam=Number(d['exam-'+t.id]);t.assignment=Number(d['assignment-'+t.id]);});activity('تحديث درجات المتدربين في JLSI-024','Trainee grades updated for JLSI-024');renderPage();toast(tr('حُفظت الدرجات وتحدّثت أهلية الشهادات.','Grades saved and certificate eligibility updated.'));}
 if(f.id==='evaluation-form'){state.evaluations.push({program:d.program,type:d.type,scores:[0,1,2,3].map(i=>Number(d['q'+i])),comments:d.comments});activity('استلام تقييم جديد للبرنامج '+d.program,'New feedback received for '+d.program);renderPage();modal(tr('شكرًا لمشاركتك','Thank you for your feedback'),`<div class="success-box">${tr('حُفظ تقييمك وأُضيف إلى مؤشرات التقارير.','Your evaluation was saved and included in report metrics.')}</div><div class="form-actions"><a class="btn" href="reports.html">${tr('عرض التقارير','View reports')}</a>${btn(tr('إغلاق','Close'),'close-modal')}</div>`);}
 if(f.id==='expense-form'){const id='PAY-'+String(Math.max(303,...state.expenses.map(x=>Number(x.id.split('-')[1])))+1);state.expenses.unshift({...d,id,amount:Number(d.amount),status:'pending',type:'other'});activity('إضافة طلب صرف '+id,'Payment request created: '+id);closeModal();renderPage();toast(tr('أُرسل المصروف للمراجعة التجريبية.','Expense submitted for demo review.'));}
 if(f.id==='settings-form'){state.settings.attendance=Number(d.attendance);state.settings.passing=Number(d.passing);state.settings.largeText=!!d.largeText;save();shell();toast(tr('حُفظت الإعدادات.','Settings saved.'));}
 if(f.id==='upload-form'){const file=f.elements.file.files[0];if(file.size>500*1024){toast(tr('حجم المرفق يتجاوز ٥٠٠ كيلوبايت.','Attachment exceeds 500 KB.'));return;}if(!/\.(pdf|png|jpe?g|txt)$/i.test(file.name)){toast(tr('يرجى اختيار PDF أو صورة أو ملف نصي.','Choose a PDF, image or text file.'));return;}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const item={id:'file-'+Date.now(),title:d.title||file.name,name:file.name,program:d.program,data};const collection=f.dataset.kind==='media'?state.media:state.materials;collection.push(item);if(!save()){collection.pop();return;}closeModal();renderPage();toast(tr('حُفظ المرفق محليًا.','Attachment saved locally.'));}
});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const controls=$$('.modal a,.modal button,.modal input,.modal select,.modal textarea').filter(x=>!x.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
shell();
})();
